def sort_strings_by_ascii_sum(strings_list):
    """
    Sorts a list of strings based on the sum of ASCII values of their alphabetic characters in descending order.
    In case of a tie, sorts the strings lexicographically in ascending order.

    Parameters:
    strings_list (list): A list of strings to be sorted.

    Returns:
    list: A new sorted list of strings.

    Raises:
    TypeError: If the input is not a list of strings.
    """

    # Helper function to validate the input
    def validate_input(lst):
        if not isinstance(lst, list):
            raise TypeError("Input must be a list of strings.")
        for item in lst:
            if not isinstance(item, str):
                raise TypeError("All elements in the list must be strings.")

    # Helper function to calculate the ASCII sum of alphabetic characters in a string
    def ascii_sum(s):
        return sum(ord(c) for c in s if c.isalpha())

    # Compare two strings based on the specified criteria
    def compare(s1, s2):
        sum1, sum2 = ascii_sum(s1), ascii_sum(s2)
        if sum1 > sum2:
            return -1  # s1 should come before s2
        elif sum1 < sum2:
            return 1   # s1 should come after s2
        else:
            if s1 < s2:
                return -1
            elif s1 > s2:
                return 1
            else:
                return 0

    # Merge two sorted lists into one sorted list based on the compare function
    def merge(left, right):
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            cmp = compare(left[i], right[j])
            if cmp <= 0:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        # Append any remaining elements
        while i < len(left):
            merged.append(left[i])
            i += 1
        while j < len(right):
            merged.append(right[j])
            j += 1
        return merged

    # Recursive merge sort implementation
    def merge_sort(lst):
        if len(lst) <= 1:
            return lst
        mid = len(lst) // 2
        left_sorted = merge_sort(lst[:mid])
        right_sorted = merge_sort(lst[mid:])
        return merge(left_sorted, right_sorted)

    # Validate the input
    validate_input(strings_list)

    # Handle empty list
    if not strings_list:
        return []

    # Perform merge sort and return the sorted list
    return merge_sort(strings_list)

# Example usage:
