```python
import math

def transform_value(value):
    if isinstance(value, str) and value == '':
        return 0
    elif isinstance(value, (int, float)) and (math.isnan(value) or value < 0):
        return 0
    elif isinstance(value, int) and value > 0 and value % 2 == 0:
        return 1
    elif isinstance(value, list):
        return [transform_value(v) for v in value]
    elif isinstance(value, dict):
        return {k: transform_value(v) for k, v in value.items()}
    else:
        return value

def test_transform_value():
    # Test cases
    assert transform_value([5, -2, 3, None, '', 8]) == [1, 0, 3, 0, 0, 1]
    assert transform_value({'a': 1, 'b': '', 'c': None, 'd': [1, '', None]}) == {'a': 1, 'b': 0, 'c': 0, 'd': [1, 0, 0]}
    assert transform_value([1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]) == [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}]
    assert transform_value('') == 0
    assert transform_value(-5) == 0
    assert transform_value(float('nan')) == 0
    assert transform_value(4) == 1
    assert transform_value(3) == 3
    assert transform_value({'a': 2, 'b': [4, 5]}) == {'a': 1, 'b': [1, 1]}
    assert transform_value([{'a': 2}, [4, {'b': 5}]]) == [{'a': 1}, [1, {'b': 5}]]

# Run tests
test_transform_value()
print("All tests passed.")
