def merge_and_sort_descending(list1, list2):
    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        return merge(left, right)

    def merge(left, right):
        result = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] > right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result

    merged_list = list1 + list2
    return merge_sort(merged_list)

# Test cases
print(merge_and_sort_descending([10, 8, 6, 2], [9, 7, 4, 3]))  # Expected: [10, 9, 8, 7, 6, 4, 3, 2]
print(merge_and_sort_descending([], [9, 7, 4, 3]))             # Expected: [9, 7, 4, 3]
print(merge_and_sort_descending([10, 8, 6, 2], []))            # Expected: [10, 8, 6, 2]
