import numpy as np
import itertools
import random

def task_func(T1, max_value=100):
    if not T1:
        return (0, 0, 0)

    try:
        # Convert all string elements to integers and flatten the tuple of tuples
        flat_ints = list(itertools.chain.from_iterable(int(item) for item in subtuple) for subtuple in T1)
        flat_ints = list(itertools.chain.from_iterable(flat_ints))
    except ValueError:
        raise ValueError("All elements in T1 must be string representations of integers.")

    total_size = sum(flat_ints)

    if total_size == 0:
        return (0, 0, 0)

    # Generate a list of random integers with the specified total size
    random_list = [random.randint(0, max_value) for _ in range(total_size)]

    # Calculate the 25th, 50th, and 75th percentiles
    p25, p50, p75 = np.percentile(random_list, [25, 50, 75])

    return (p25, p50, p75)
