    if isinstance(data, pd.DataFrame):
        if data.shape[1] != 1:
            return "Error: Input DataFrame must have exactly one column."
        data_series = data.iloc[:, 0]
    elif isinstance(data, pd.Series):
        data_series = data
    elif isinstance(data, (list, tuple)):
        data_series = pd.Series(data)
    else:
        return "Error: Unsupported data type. Provide a list, tuple, pandas Series, or single-column DataFrame."

    # Check if all elements are categorical (strings or categorical dtype)
    if not pd.api.types.is_object_dtype(data_series) and not pd.api.types.is_categorical_dtype(data_series):
        return "Error: Input data contains non-categorical values."

    # Handle missing values
    if data_series.isnull().any():
        return "Error: Input data contains missing values."

    try:
        # Initialize LabelEncoder
        encoder = LabelEncoder()
        # Fit and transform the data
        encoded = encoder.fit_transform(data_series)
        # Create the resulting DataFrame
        result_df = pd.DataFrame({
            'Category': data_series,
            'Encoded': encoded
        })
        return result_df
    except Exception as e:
        return f"Error: {str(e)}"
