import math
import statistics
import numpy as np

def task_func(input_list):
    if not input_list:
        return (None, None, None, None, None, None)

    # Sort the list in ascending order
    sorted_list = sorted(input_list)

    # Calculate mean, median, and mode of the sorted list
    try:
        mean_val = round(statistics.mean(sorted_list), 2)
    except statistics.StatisticsError:
        mean_val = None

    try:
        median_val = round(statistics.median(sorted_list), 2)
    except statistics.StatisticsError:
        median_val = None

    try:
        mode_val = round(statistics.mode(sorted_list), 2)
    except statistics.StatisticsError:
        # If no unique mode, set to None
        mode_val = None

    # Calculate FFT and its magnitude
    fft_result = np.fft.fft(sorted_list)
    magnitudes = np.abs(fft_result)

    # Calculate mean, median, and mode of FFT magnitudes
    try:
        fft_mean = round(np.mean(magnitudes), 2)
    except:
        fft_mean = None

    try:
        fft_median = round(np.median(magnitudes), 2)
    except:
        fft_median = None

    try:
        # To handle floating point precision issues, round magnitudes before finding mode
        rounded_magnitudes = [round(mag, 2) for mag in magnitudes]
        fft_mode = round(statistics.mode(rounded_magnitudes), 2)
    except statistics.StatisticsError:
        fft_mode = None

    return (mean_val, median_val, mode_val, fft_mean, fft_median, fft_mode)
