        data = pd.DataFrame([
            {'Name': 'Alice', 'Age': 20},
            {'Name': 'Bob', 'Age': 25}
        ])
        with self.assertRaises(KeyError):
            task_func(data)

    def test_non_df(self):
        with self.assertRaises(ValueError):
            task_func("non_df")

