```python
import os
import json
from collections import Counter

def task_func(json_files_path='./json_files/', key='name'):
    """
    Count the occurrence of a particular key in all JSON files within a specified directory.

    Parameters:
        json_files_path (str): The path to the directory containing JSON files.
        key (str): The key to count occurrences of.

    Returns:
        dict: A dictionary with the values of the key as keys and their counts as values.
              Returns an empty dictionary if no files contain the specified key.
    """
    if not os.path.isdir(json_files_path):
        print(f"Error: The directory '{json_files_path}' does not exist or is inaccessible.")
        return {}

    counter = Counter()
    json_files = [file for file in os.listdir(json_files_path) if file.lower().endswith('.json')]

    if not json_files:
        print(f"No JSON files found in the directory '{json_files_path}'.")
        return {}

    for file_name in json_files:
        file_path = os.path.join(json_files_path, file_name)
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                data = json.load(file)

                # Handle nested JSON objects by flattening if necessary
                if isinstance(data, list):
                    items = data
                else:
                    items = [data]

                for item in items:
                    if isinstance(item, dict) and key in item:
                        value = item[key]
                        counter[value] += 1
        except json.JSONDecodeError:
            print(f"Warning: The file '{file_name}' contains invalid JSON and will be skipped.")
        except Exception as e:
            print(f"Warning: An error occurred while processing '{file_name}': {e}")

    return dict(counter)
