import itertools
import json

def task_func(json_list, r):
    if not json_list:
        raise Exception("JSON input is empty")

    try:
        data = json.loads(json_list)
    except json.JSONDecodeError:
        raise Exception("Invalid JSON input")

    if not isinstance(data, dict):
        raise Exception("JSON data is not an object")

    if 'number_list' not in data:
        raise Exception("'number_list' key is missing in JSON data")

    number_list = data['number_list']

    if not isinstance(number_list, list):
        raise Exception("'number_list' must be a list")

    if r > len(number_list):
        return []

    return list(itertools.combinations(number_list, r))
```

