import unittest
from typing import List

# Define the line classes
class StringLine:
    def __init__(self, content: str):
        self.content = content

    def __eq__(self, other):
        return isinstance(other, StringLine) and self.content == other.content

    def __repr__(self):
        return f"StringLine(content={self.content!r})"

class EmptyStringLine:
    def __eq__(self, other):
        return isinstance(other, EmptyStringLine)

    def __repr__(self):
        return "EmptyStringLine()"

class CellSeparatorLine:
    def __eq__(self, other):
        return isinstance(other, CellSeparatorLine)

    def __repr__(self):
        return "CellSeparatorLine()"

class DatabricksCellSeparatorLine:
    def __init__(self):
        self.content = "%md"

    def __eq__(self, other):
        return isinstance(other, DatabricksCellSeparatorLine) and self.content == other.content

    def __repr__(self):
        return f"DatabricksCellSeparatorLine(content={self.content!r})"

# Transformer class
class CellSeparatorsTransformer:
    def transform(self, lines: List) -> List:
        transformed_lines = []
        for line in lines:
            if isinstance(line, CellSeparatorLine):
                transformed_lines.append(DatabricksCellSeparatorLine())
            else:
                transformed_lines.append(line)
        return transformed_lines

# Unit tests
class TestCellSeparatorsTransformer(unittest.TestCase):
    def setUp(self):
        self.transformer = CellSeparatorsTransformer()

    def test_empty_list(self):
        self.assertEqual(self.transformer.transform([]), [])

    def test_no_cell_separators(self):
        lines = [
            StringLine("print('Hello, world!')"),
            EmptyStringLine(),
            StringLine("x = 42")
        ]
        expected = [
            StringLine("print('Hello, world!')"),
            EmptyStringLine(),
            StringLine("x = 42")
        ]
        self.assertEqual(self.transformer.transform(lines), expected)

    def test_all_cell_separators(self):
        lines = [
            CellSeparatorLine(),
            CellSeparatorLine(),
            CellSeparatorLine()
        ]
        expected = [
            DatabricksCellSeparatorLine(),
            DatabricksCellSeparatorLine(),
            DatabricksCellSeparatorLine()
        ]
        self.assertEqual(self.transformer.transform(lines), expected)

    def test_mixed_lines(self):
        lines = [
            StringLine("import sys"),
            CellSeparatorLine(),
            EmptyStringLine(),
            StringLine("def foo():"),
            CellSeparatorLine(),
            StringLine("    return 'bar'"),
            CellSeparatorLine()
        ]
        expected = [
            StringLine("import sys"),
            DatabricksCellSeparatorLine(),
            EmptyStringLine(),
            StringLine("def foo():"),
            DatabricksCellSeparatorLine(),
            StringLine("    return 'bar'"),
            DatabricksCellSeparatorLine()
        ]
        self.assertEqual(self.transformer.transform(lines), expected)

    def test_single_cell_separator(self):
        lines = [CellSeparatorLine()]
        expected = [DatabricksCellSeparatorLine()]
        self.assertEqual(self.transformer.transform(lines), expected)

    def test_single_non_separator_line(self):
        lines = [StringLine("print('Single line')")]
        expected = [StringLine("print('Single line')")]
        self.assertEqual(self.transformer.transform(lines), expected)

