```python
def convert_to_emoji(input_string):
    """
    Converts words in the input_string to their corresponding emoji codes
    based on a predefined mapping. Words that do not match any emoji representation
    are left unchanged.

    Args:
        input_string (str): The string to be converted.

    Returns:
        str: The converted string with emoji codes.
    """
    # Dictionary mapping plain text representations to emoji codes
    emoji_mapping = {
        ":)": ":smile:",
        ":(": ":sad:",
        ":D": ":grin:",
        ":P": ":stuck_out_tongue:",
        ";)": ":wink:",
        ":O": ":surprised:",
        "XD": ":laughing:",
        ":'(": ":cry:",
        "<3": ":heart:",
        ":/": ":confused:",
        ":|": ":neutral:",
        ":*": ":kiss:",
        ":@": ":angry:",
        ">:(": ":mad:",
        ":$": ":embarrassed:",
        ">:O": ":shocked:",
        ">:D": ":evil_grin:",
        ":^)": ":smirk:"
    }

    # Split the input string into words
    words = input_string.split()

    # Replace words with corresponding emoji codes if they exist in the mapping
    converted_words = [
        emoji_mapping.get(word, word) for word in words
    ]

    # Join the converted words back into a single string
    return ' '.join(converted_words)


# Test cases to verify the correctness of the convert_to_emoji function
