        },
        {
            "input": "No emoji here!",
            "expected": "No emoji here!"
        },
        {
            "input": "Mixed emotions :) :(",
            "expected": "Mixed emotions :smile: :sad:"
        },
        {
            "input": "Surprised :O and shocked >:O",
            "expected": "Surprised :surprised: and shocked :shocked:"
        },
        {
