            "expected": "Laughing :laughing: and mad :evil_grin:"
        },
        {
            "input": "Smirk :^)",
            "expected": "Smirk :smirk:"
        },
        {
            "input": "Embarrassed :$",
            "expected": "Embarrassed :embarrassed:"
        },
        {
            "input": "Neutral :| expression",
            "expected": "Neutral :neutral: expression"
        }
    ]

    passed = 0
    for idx, test in enumerate(test_cases, 1):
        result = convert_to_emoji(test["input"])
